// Generates src/inject/script.generated.ts from src/inject/clean-instagram.js.
// Run: npm run gen:inject   (a test fails if the generated file is stale)
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = readFileSync(join(root, 'src/inject/clean-instagram.js'), 'utf8').trim().replace(/;\s*$/, '');
const out =
  '// AUTO-GENERATED by scripts/gen-inject.mjs from clean-instagram.js. Do not edit.\n' +
  `export const CLEAN_INSTAGRAM_SOURCE: string = ${JSON.stringify(src)};\n`;
const target = join(root, 'src/inject/script.generated.ts');
if (process.argv.includes('--check')) {
  const current = readFileSync(target, 'utf8');
  if (current !== out) {
    console.error('script.generated.ts is stale. Run npm run gen:inject');
    process.exit(1);
  }
  console.log('script.generated.ts is up to date');
} else {
  writeFileSync(target, out);
  console.log('wrote', target);
}
